    async function frontdoor_criterion(fpaths, adjust) {
        // console.log("FRONTDOOR CRITERION")
        // initialize condition states: condition 1 ; condition 2 ; condition 3
        let [c1, c2, c3] = [false, false, false]
        // CONDITION 1 : Z intercepts ALL directed paths from X to Y : These paths are given by the variable frontdoors
        c1 = fpaths.map(path => {
            let path_set = new Set(path)
            let intercepted = false
            adjust.forEach(conditioner => {
                if (path_set.has(inv_nn[conditioner])) {
                    // console.log(path, " is intercepted by : ", inv_nn[conditioner])
                    intercepted = true
                }
            })
            return intercepted
        })
        if (new Set(c1).has(false)) {
            // console.log(c1)
            // console.log("Condition 1 not met: The set Z does not block all paths")
            return "Condition 1 not met: The set Z does not block all paths"
        }
        // console.log("PASSED CONDITION 1")
        // CONDITION 2 : There is no unblocked back-door path from X to Z
        let trt_names = []
        let conditioners = []
        let out_names = []
        treatments.forEach((trt, i) => {
            trt_names.push(inv_nn[trt])
        })
        adjust.forEach((conditioner => {
            conditioners.push(inv_nn[conditioner])
        }))
        outcomes.forEach((outcome => {
            out_names.push(inv_nn[outcome])
        }))
        // console.log("Treatments: ", trt_names)
        // console.log("Conditioners: ", conditioners)
        let x_z = []
        for await (const treatment of trt_names) {
            console.log(treatment)
            let xi_zi = []
            for await (const conditioner of conditioners) {
                fetch("http://127.0.0.1:5000/backdoors/" + model_name + "/" + treatment + "/" + conditioner)
                    .then(res => res.json())
                    .then(json => {
                        console.log("RESPONDED ")
                        backdoors = [...json["backdoors"]]
                        let backdoor_output = "";
                        let backdoor_colliders_detected = [];
                        treatments.forEach((treatment, i) => {
                            adjust.forEach((adjustment, j) => {
                                if (backdoors.length > 1) {
                                    console.log(backdoors[i][j])
                                } else {
                                    if (backdoors[i].length > 0) {
                                        backdoor_output = backdoor_output + "===== (" + inv_nn[treatment] + ", " + inv_nn[adjustment] + ") ======\n"
                                        backdoors[i].forEach((path, k) => {
                                            path.forEach((node_name, l) => {
                                                if (l >= 1 && l < path.length - 1) {
                                                    previous = nn[path[l - 1]]
                                                    current = nn[path[l]]
                                                    next = nn[path[l + 1]]
                                                    //  is the middle node a descendant of both previous and next
                                                    let middle_parents = new Set(parent_child[current])
                                                    if (middle_parents.has(previous) && middle_parents.has(next)) {
                                                        backdoor_colliders_detected.push([path, current, i, j, k])
                                                    }
                                                }
                                            }, i, j, k)
                                            k = k + 1
                                            backdoor_output = backdoor_output + "(" + k + ") " + path + "\n"
                                        }, i, j)
                                        xi_zi.push(backdoors[i])
                                        backdoor_output += "\n"
                                    }
                                };
                            })
                        })
                    })
            }
            if (xi_zi.length > 0) {
                x_z.push(true)
            } else {
                x_z.push(false)
            }
        }
        x_z = new Set(x_z)
        if (x_z.has(true)) {
            // console.log("Failed condition 2")
            return "Failed condition 2"
        }
        // console.log("PASSED CONDITION 2  ")
        let z_y = []
        //  CONDITION 3 : All back-door paths from Z to Y are blocked by X.
        for await (const conditioner of conditioners) {
            let zi_yi = []
            for await (const outcome of out_names) {
                console.log(outcome)
                fetch("http://127.0.0.1:5000/backdoors/" + model_name + "/" + conditioner + "/" + outcome)
                    .then(res => res.json())
                    .then(json => {

                        backdoors = [...json["backdoors"]]
                        console.log("Responded w/ backdoors : ", backdoors)
                        let backdoor_output = "";
                        let backdoor_colliders_detected = [];
                        adjust.forEach((adjustment, i) => {
                            outcomes.forEach((outcome, j) => {
                                if (backdoors.length > 1) {
                                    console.log("backdoors: ", backdoors[i][j])
                                } else {
                                    if (backdoors[i].length > 0) {
                                        backdoor_output = backdoor_output + "===== (" + inv_nn[adjustment] + ", " + inv_nn[outcome] + ") ======\n"
                                        backdoors[i].forEach((path, k) => {
                                            path.forEach((node_name, l) => {
                                                if (l >= 1 && l < path.length - 1) {
                                                    previous = nn[path[l - 1]]
                                                    current = nn[path[l]]
                                                    next = nn[path[l + 1]]
                                                    //  is the middle node a descendant of both previous and next
                                                    let middle_parents = new Set(parent_child[current])
                                                    if (middle_parents.has(previous) && middle_parents.has(next)) {
                                                        backdoor_colliders_detected.push([path, current, i, j, k])
                                                    }
                                                }
                                            }, i, j, k)
                                            k = k + 1
                                            backdoor_output = backdoor_output + "(" + k + ") " + path + "\n"
                                        }, i, j)
                                        zi_yi.push(backdoors[i])
                                        backdoor_output += "\n"
                                    }
                                };
                            })
                        })
                    })
            }
            if (zi_yi.length > 0) {
                z_y.push(true)
            } else {
                z_y.push(false)
            }
        }

        z_y = new Set(z_y)
        if (z_y.has(true)) {
            // console.log("Failed condition 3")
            return "Failed condition 3"
        } else {
            // console.log("PASSED CONDITION 3")
        }

    }

